import type { PoseAngles } from "../rig.ts";
import { STAND } from "../rig.ts";
import type { MoveSettings, Stance } from "./motion.ts";
import type { MoveEntry } from "./plan.ts";
import { MOVE_SPEEDS, MOVE_STYLES, RAMP_SCALE, STYLE_CHANGES } from "./styles.ts";

// SPEC-0017 Phase 2: lessons for the AI director, made automatically from the moves library (so they
// can never disagree with the real moves). Phase 3 gives these to the AI before it plans a scene: the
// library's key poses and timing are the "5 + 5 = 10" examples; the principles explain WHY they look
// natural, so it can invent new moves ("3 + 3") that still look natural. The engine still makes every
// frame and checks every body rule.

export const PRINCIPLES = [
  "The AI never draws frames. It writes a plan: characters, actions in order, knobs (style, speed, energy), and timing between characters. New moves are written as a few KEY POSES with beat kinds; the engine makes every in-between frame and enforces the body rules.",
  "Almost every movement is: ANTICIPATION (a slow wind-up the opposite way, e.g. lean back before a punch, crouch before a jump) -> ACTION (speeds up fast into the hit/jump/throw) -> FOLLOW-THROUGH (slows down past the target) -> SETTLE (eases back to rest). The wind-up is slow; the action is fast. Then the next movement starts.",
  "Everything speeds up and slows down: starting to walk or run takes about half a second (small steps and small arm swings growing to full); stopping takes about half a second. A slow run swings the arms only a little. Tired, heavy, hurt or low-energy bodies take longer; lively or angry ones are quicker. Only a robot starts and stops at full speed, with no wind-up.",
  "Weight: knees bend to absorb every landing; the body leans into effort; planted feet never slide; a punch or kick shifts the weight onto the back foot first, then drives forward.",
  "Body rules: bones never stretch; elbows and knees bend only the natural way; nothing goes through the floor; a knee never touches the floor in a crouch.",
  "Page rule: the whole animation is centered on the page and always stays fully inside it; figures never change size to fit (they cover less ground instead).",
  "Looks: by default a classic stick figure — solid head sitting right on the body, no neck. Options: hollow head, a neck, a color per figure, thickness, head size.",
  "Turning around passes through facing the viewer for a moment; side-view moves (walk, run, punch...) need the figure facing left or right.",
  "Everything the engine makes becomes ordinary, editable frames on a new layer: the user can erase, redraw, select and stretch anything afterwards.",
  "FLOW: moves that follow each other hand over directly (punch -> punch from the guard, run -> grab without standing up first). Only go back to a rest pose when needed: before walking/running, before a long pause, at the end. Punches in a row alternate hands. A kick's foot comes down once, straight into the next pose — never down, up and down again.",
  "INPUT BEHIND, OUTPUT IN FRONT: the wind-up (input) always goes the OPPOSITE way from the action, back toward and behind the body; only the action (output) happens in front. Picture a dot where the strike must land: the wind-up goes the opposite way from that dot, then the strike hits the bullseye — whether the dot is level, above the head or at the waist. A straight punch draws its elbow back (opposite the target) to a little behind the spine; a punch that comes DOWN winds up UP and back (elbow behind the head); a punch that goes UP (uppercut) winds up DOWN and back (fist beside the hip, knees dipping); a kick swings the leg back behind the body. Even the smallest wind-up lasts at least 2-3 pictures at 12 fps, so it is seen. The arms counter-move: while one fist goes out the other hand pulls back to the face (left, right, left, right like pistons).",
  "THE SIZE OF A WIND-UP FOLLOWS THE POWER: a small action (a jab, a light tap) is a strong one in MINIATURE, seen for a moment — a jab or quick cross: the elbow goes back to a little behind the spine, the arm folded with the fist tucked in by the chest, the other hand up by the face, then the fist goes straight to the target; a strong action takes the full wind-up: for an overhand punch the elbow lifts and goes behind the head, the other arm points at the target, the body leans back; then the FIST LEADS forward, the elbow follows, the arms switch and the body leans forward into the hit. A throw winds up the same way, the ball above and behind the head.",
  "A raised arm turns at the shoulder, so in a side view its elbow may look bent either way (a cocked throwing arm: upper arm back, forearm up); a lowered arm bends only the natural way.",
  "CONTACT: a hand is the very end of the forearm, a foot the very end of the leg. Things that touch (two hands in a high-five, a hand and a ball, a fist and a target) meet at those ends, just touching — never passing through or crossing.",
  "REST WHILE WAITING, READY JUST IN TIME: when a figure has to wait for its moment (the ball coming back), it settles into its resting stand and breathes (holding things at the chest), instead of freezing in the last move's leftover pose or holding its arms out for ages; just before its moment it gets ready (hands come up as the ball is thrown), then acts.",
  "ARMS BALANCE THE LEGS: whenever the legs step (walk, run, any style, even sneaky or tired), the arms swing opposite to them and pass each other every step; their weight helps the body along. Getting going, the swings start small and grow each step; stopping, they shrink each step into the stand. Slow steps = slow swings, fast steps = fast swings; more speed = bigger swings and more forward lean.",
  "CARRYING (CARRY BY WEIGHT, round 11: \"Anything he holds is a symbol... whether it's heavy or not\"): walking, jogging or running with something, how heavy it is (its size, or the object's `weight`) says how it is carried. Light (a ball): in ONE hand down at the side against the hip, the other arm swinging exactly as in the gait, legs and lean unchanged, never held out in front. Medium (a box): both hands close against the body, not swinging. Heavy: both arms low against the body, slower shorter steps, leaning back a little. Going into the carry takes a moment (never one picture) and the thing touches the hand(s) every picture. HANDS BUSY: holding something, a move that needs one hand (a high-five, a wave, a punch) first takes the thing in the other hand.",
  "HOLDING THROUGH EVERY MOVE: as long as a figure holds something it is visibly in its hand(s) on every frame, whatever the move. Moves whose arms only help the body (a kick, squat, jump, stomp, sitting, catching its breath, looking round) keep it in both hands at the chest — held the way its size needs (small: hands close together; big: hands wide apart) and lifted clear of the floor when bending low; a move that does something with one hand (a wave, a punch) takes it in the other hand, and both hands take it again after; a turn carries it in one hand. A FALL is the exception: the hands are needed to catch the body, so they let go as it trips or slips — the thing keeps the body's speed, drops, bounces and rolls (a box slides) to a stop and lies there.",
  "MOMENTUM: a body keeps going the way its weight is going. A trip while running doesn't stop first: the runner pitches forward at speed, lands on the hands and chest, slides a little, and gets up slowly because it hurt. A fall should never look intentional (unless it is), and a fall never ends sitting.",
  "DASH (dashPunch): a dash is a burst out of a run at top speed, never from nowhere: the planner runs it up (or it takes the run before it). On one foot it bends LOW (the wind-up goes down and back), pushes the leg out straight behind and shoots forward FASTER than it ran, low and flat. In the air UNDER HALF A SECOND (a longer flight looks like floating), with ANTICIPATION LOADED EARLY AND HELD (Arthur, rounds 11-12: \"when he's airborne, the arm that's going to attack is behind him\"): from the gather foot the punching fist goes back and up, and from the PUSH-OFF it is fully loaded — fist cocked by the head, elbow out BEHIND him, the body leaning BACK more than at the push, the other arm straight out in front at face height (almost blocking his face) — and it HOLDS the whole flight (4+ pictures at 12 a second in a normal dash); the front knee lifted high (less in a short hop), the back leg stretched out behind. The front foot lands the SAME MOMENT the fist lands, and the wind-up ACCELERATES (round 12: the cocked fist keeps going further back, slowly at first, faster toward the landing: ease-in). Only then THE ARMS SWITCH, FAST (the last ~0.15 s): an OVERHAND — the fist comes over the shoulder by the ear (the elbow drops by the side: never round the outside of the head) and goes STRAIGHT and LEVEL into the target's FACE (arm at most ~16 degrees up, never down at the chest), the body nearly upright like a standing punch; the reaching arm pulls back behind. IMPACT you can see: a HIT STOP — the arm held fully out on the face ~0.15 s (about 2 pictures at 12 a second) while the target's head snaps back, torso and back leg still driving in. Then a little skid and ONE step (the back foot comes up under the body) and it ENDS STANDING: hips over the feet, upright, knees nearly straight, feet a hip width apart, hands low and loose — never a lunge, half-squat or leaning-back pose.",
  "A DASH TAKES OFF FAR OUT: the leap starts about as far from the target as in the passed dash punch (never right in front of them); it covers the gap in the air and the punch lands as the feet come down.",
  "SQUASH & STRETCH AT HIGH FPS: with stick figures squash and stretch only reads at high frame rates (20 pictures a second and up); at 12 and below it looks weird, so it is never there. It is one or two extra pictures at a big push or landing (a key with `minFps`: the engine leaves it out below that rate): just before, a deeper squash (hips lower, leaning in more); just after, a stretch (head, body and push leg in one long straight line). Bones never stretch: squash and stretch is in the pose only, and the move must look right without it.",
  "RUNNING JUMP (momentum): a jump after a walk or run never stops first. The last step sinks a little (the wind-up goes DOWN before the jump goes UP) with both arms swinging back; the take-off foot plants in front, the leg drives the body up and forward off ONE foot, the free knee drives up, the arms swing forward and up. NO SLOW-DOWN: through the gather, the take-off and the flight the body never goes slower than the run (each push-off adds a little speed); the run's speed carries on in the air (faster run = longer jump; gravity sets the arc; a body in the air can't brake, so a jump is never shorter than its speed gives), the knees tuck up to clear, then the legs reach forward and both feet land, knees bending to soak it up, body pitching forward. A run straight after it RUNS ON from the landing (the back foot swings through into the next stride): run, jump, land, run, jump... with no stop. `distance` (px, take-off foot to landing foot) and `height` (x body height, the feet at the top) make it clear something placed there.",
  "PUNCH LINE: a punch sends the fist STRAIGHT to the target and the arm ends level (the most common punch is straight, not up, not down; punching up is the uppercut's job). From a big wind-up (elbow behind the head) the fist first comes forward past the head to the shoulder, the elbow drops under it, then the fist travels a straight line to the target while the other arm goes back behind the body (the arms switch) and the body leans forward into it. Only an overhand (asked for, or at a low target like someone bent over) arcs over and comes DOWN onto the target. The elbow never circles the head.",
  "THE END OF A FIGHT: a fight doesn't end by standing up tall: the figure stays in its fighting stance, as tired as its effort, for only a moment. RESTING HANDS: once the fighting is done the hands sink so you can SEE it is resting — clearly lower than in its fighting stance, below the chest (a little tired: just under the chest; very tired: elbows by the sides, hands down at the belly), still in front with the forearms pointing forward, never hanging straight down; more effort also = knees sagging, quicker breathing, the back leaning only a little. REALLY tired (about twice the effort that tires a body, or a tired/hurt body after a long fight) it bends over right where it stands, arms locked straight down onto its knees, and stays there breathing. (Outside a fight, a lot of effort ends bent over, hands on knees, arms straight.)",
  "SMALL BREATHS: humans breathe hard but only move a little. Hard breathing shows in QUICK breaths, not big ones: each breath lifts the chest and shoulders a few pixels (about 1% of the height), the head a touch, and the hands only ride along with the shoulders (no pumping arms). Hands propped on the knees stay on the knees with straight arms.",
  "KICK PACE: a kick's wind-up is as big as its power needs, no bigger: the leg swings back until the foot is a little behind the hip at about knee height (further for a strong kick, less for a tired one), still clearly behind the body (input behind). The wind-up's slow-before-fast rule then sets its time from how far the foot travels, so a kick is only a little longer than a big punch, never twice as long.",
  "BALANCE: a body standing on its feet keeps its weight (centre of mass: torso, head, arms, legs) over its feet — between the back heel and the front toes, with room to spare — or it would fall. So a big forward lean needs the hips pushed BACK with the knees bent, and/or the hands on the knees (bent over, out of breath); a tired body that only sags (a tired fighting stance) leans just a little, knees bent, hands low. The engine places the hips from the pose and the planted feet.",
  "PICK THE TECHNIQUE FROM THE DISTANCE: close target = uppercut; medium = straight punch with only a tiny pull-back; far or a big power shot = a power punch with the full wind-up (still straight at the target); a low target = overhand. Throwing: a short throw is an underhand toss; only a long throw needs the overhand.",
  "PASSING BY REACH AND SPEED: if two people can meet half way (arms out, at most one small step), nobody throws — one holds it out, the other takes it with both hands. Further = an underhand toss; only when the ball needs more speed than an underhand swing gives = overhand. An overhand winds up BEHIND the head: the elbow goes up and back behind the head (in a side view it can pass behind the head — that reads as 3D), the ball above and behind it, held a moment; the elbow then leads over and the forearm snaps through. Arms never sweep straight out round the head and never spin a full circle.",
  "A HELD THING TOUCHES THE HANDS (contact): while someone holds a ball its edge is always at their hand(s) — both hands for a two-handed hold — never floating beside them. It only leaves the hands in a throw (the hands moving fast); nobody touches it in flight. A HAND-OFF goes straight from hands to hands: the giver holds it out still, both hands on it, until the taker's hands are on it too, and only then lets go and drops its arms; the taker reaches to exactly where it is held (a step if needed). A catch closes the hands on the ball exactly when it arrives. Face whoever you pass to or catch from (turn to them first).",
  "THE BALL OBEYS GRAVITY AFTER IT LEAVES THE HAND: a pass flies on an arc; a bounce pass goes down to the floor once and rises into the catcher's hands (the catch is timed to it); a ball thrown away arcs off the page and is gone (it doesn't come back, and it doesn't make the scene smaller to fit).",
  "ARMS HANG BY GRAVITY: an arm swing is centred on straight down, not on the body's lean: the hand reaches as far in front of the shoulder as behind it, walking or running, whatever the lean or elbow bend. Running arms are loose and big and swing AROUND THE BODY: a runner leans forward, so the hand goes as far behind his back as in front of his chest (front-back, left-right on screen, never just up and down); the elbow bends as the arm comes forward and opens out as it goes back (never locked at 90 degrees). The legs too: about as much stride in front of the hips as behind, a clear moment in the air every step (contact, push-off, airborne, passing...), the body leaning as if falling forward.",
  "ARRIVE INTO IT: a walk or run that ends in a move going down (picking something up, squatting, sitting) stops still leaning in and goes straight down; the braking steps are the wind-up, so there is no standing pose and no extra lean back in between.",
  "SEEN, NOT A BLUR: a move must be readable at 12 pictures a second. Even the fastest running step lasts about 4 pictures; a faster runner covers more ground per step instead of stepping faster.",
  "ANY FRAME RATE: every animation follows the project's frames per second (8, 10, 12, 13, 15, 24, 30...) with the same timing in seconds, just fewer or more pictures. Name the key moments of a move (hit, take-off, top, landing, release, catch, slap): below 12 pictures a second (8, 10) the engine gives each named moment a picture of its own, so a punch's hit or a landing is never lost between two pictures; from 12 up the pictures stay evenly spaced so steady motion never stutters.",
  "WALK, JOG, RUN: three speeds on foot. A walk always has a foot down (both down for a moment each step). A JOG is nearly twice walking speed with a SHORT, LOW hop every step (well under half a second, the feet just clearing the floor; Arthur: 'jogging, you're actually airborne a little', with no hop it looks like walking): short quick steps, soft knees, a small bounce, arms bent near 90 degrees pumping small. A RUN is for a real hurry: about twice a jog's speed (more than three times a walk's), with a clear moment in the air every step.",
  "AIRBORNE (a run): every step has a moment with both feet clearly off the ground: the back foot has just pushed off and the front foot hasn't landed yet. The legs do NOT switch in the air: the leg in front at the push-off is the one that lands in front. Legs (and arms) pass each other only while a foot is on the ground (Arthur: 'they only switch when you hit the ground'). In the air the back heel kicks up behind right after the push-off (the knee folds early, not only while passing under the body) and the front knee is driven up high (thigh nearly level, shin hanging under it), then the front leg reaches down to land. Low, straight legs in the air read as marching.",
  "SOFT HIPS: hips never pop. When a foot leaves the ground the hips ease up (never higher than the planted legs can reach), so a walk glides with a small bounce instead of jerking, and a jog's hop is a small rise, not a jump.",
  "ARM PATHS: the body has a back. A raised arm may pass its elbow behind or through the head (in a side view that reads as 3D: a cocked punch or throw, a high-five wind-up); the hand takes the short way. An arm never loops round the outside of the head and never spins round like a windmill.",
  "ARM UP BEHIND, BACK DOWN THE SAME WAY: to raise a hand high (a high-five), the hand comes in to the chest and up past the ear while the elbow goes back and up BEHIND the head, the forearm standing up; it swings forward over the head to the target and, after, goes back down the way it came up (so it never goes round in a whole circle).",
  "ELBOWS BY THE NECK: lying face down, a body gets up the way a push-up starts: the hands flat on the floor UNDER THE CHEST, the elbows bent up and back beside the neck (never up over the head), then it pushes straight up. With the arms out past the head, the elbows first slide back along the floor under the shoulders (the chest comes up onto the forearms), then the hands come back under the chest as it sinks onto them, then the push.",
  "GO FROM WHERE YOU ARE: a crouched or bent figure that suddenly runs doesn't stand up first; it pushes off out of the crouch and its posture flows into the run during the first step.",
  "FIGHTING STEP: in a fight, closing a short gap is a shuffle in the guard (front foot in, back foot follows, guard up), not a walk.",
  "PEOPLE ARE IMPATIENT: turning around to go somewhere is quick (about 0.6 s); only a careful or slow figure turns slowly.",
  "PLANTED FEET DON'T MOVE: while a foot is on the ground the body goes wherever that foot puts it. If the next move needs the feet somewhere else (closer together after a fighting stance, before a squat or a sit), the figure first steps them there: weight onto one foot, the other lifts a little and steps to its place.",
  "ROOM: if a move can go either way (fall forward or back) and the plan doesn't say, it goes the way with more room, toward the middle of the page.",
  "ACCIDENTS HAVE A CAUSE: nobody just topples over standing still. A fall the plan doesn't aim (no direction) with nothing before it that explains it (a walk or run = a trip, a hit, a landing, a strike or stomp that overbalances) is an accident: the figure sets off walking — a step or two, speeding up — and trips mid-step, keeping its speed. Asked to fall a way (back = a slip), it falls where it stands.",
  "NO UNNECESSARY KEY POSES: a figure only goes through a pose it needs. Getting up from a fall to sit down, it gets up only part of the way (from the belly to a crouch with a hand on the knee; from the back it is sitting already) and sits straight from there — it never stands up first.",
  "EYES ON THE INJURY: a hurt figure that sits down (after a fall, or in the hurt style) stretches its legs out, leans over where it got hurt (the knee, after a trip), holds it with both hands and looks at it, rubbing it while it breathes; it draws its feet back in before getting up.",
  "NEVER TOLD: the library moves are examples, not a menu. Any order, any mix of styles, speeds and energies, any number of moves must still come out natural; the engine's rules (these principles) make that true, not a list of answers.",
  "LOOK vs TURN: to look behind, a figure only twists its shoulders (arms swing, head turns, about 90 degrees, feet stay put, about a second). It turns its whole body around only when it is going to go the other way: two steps, under a second.",
  "RUN FROM THE LOOK: a figure that looks back, sees something and runs (or walks) away starts running the moment the look is over, straight from the looking-back pose — it never turns to face forward first; the head and shoulders turn forward during the first strides.",
  "EYES: a stick figure has eyes even though they aren't drawn. It looks where it is going, and at what it is dealing with: the one it waves to, high-fives, throws to, catches from, punches or kicks (kicking at nothing: the spot its foot hits), the spot it stomps on, its own injury. The head tilts toward it (up when it is higher, down when lower, as far as a neck goes); a wave goes up toward someone high and down toward someone low; to wave at someone behind, it turns to them first. With nothing to look at, it looks where it faces.",
  "HIGH-FIVE PACE: a high-five is done at walking pace: winding up takes about one walking step of the same mood, the slap is quick. A happy figure slaps fast; an angry one marches in, stamps the lead foot down, winds up deeper and slaps really hard; a natural one is in between. The arm still goes up behind the head and comes back down the same way.",
  "ONE WAY ROUND: an arm never goes round a whole circle. After a high-five the arm is up in front, having gone up behind the head: if the next move wants it up in front again (a wave), it stays up and the next move takes it from there (a wave then skips its dip and rise, and comes down the way the arm went up); otherwise it goes back down behind the head the way it came. Pick the hand-over that turns the arm least in any second; if even that would swing it round too fast, the hand waits a moment at the hand-over first. A wave the same: if the next move would swing the waving arm on round from up high (a jump), the arm comes down first.",
  "MOODS IN PARTNER MOVES: a ROBOT keeps its arms straight and stiff and moves at even speeds that start and stop dead — its high-five arm goes straight up and round behind its head, slaps, goes back round and comes back; its throw swings the straight arm behind, round the head and out, then back round; its catch has no give (it feels no weight). A MAD figure hunches, holds its free arm out bent and slaps or throws harder (deeper wind-up). A HAPPY figure is lively: chest up, free arm flung back at the slap, a bigger bounce apart.",
  "STRIKE POWER: how hard a hit is comes from the strike itself — a lot of anticipation (a long, big wind-up) and a fist or foot that travels far and fast into the hit (an overhand, a kick) hit hard; a quick jab or a short uppercut barely does. A tired or hurt body hits softer, an angry, lively one harder.",
  "STRIKE WEIGHT: what hits matters too. A leg weighs about three times an arm, so a kick carries more into the hit than a punch moving the same way: a kick hits at least as hard as a punch with the same wind-up, even with a short wind-up of its own.",
  "THROWN OFF BALANCE (almost knocked over, either facing): the pose is the head and chest thrown BACK past the hips, one arm flung up over the head (elbow up in front of the face, forearm over the top of the head), the other elbow flung back at shoulder height, standing on the bent back leg with the front leg straight out and its foot up. The way in is a chain, each part a moment after the last: the head snaps back first, the chest follows and the weight goes onto the back foot as the front foot leaves the floor, the arms fly up last (they lag behind the body). Every part keeps going the one way it set off — no arm changes its mind, nothing flails round. Then it catches itself with a step back (ALMOST FALLS, below).",
  "ALMOST FALLS = A CATCHING STEP BACK (Arthur: \"he would take a step backwards: the leg that is in the air steps behind him... like he's almost losing balance\"): thrown into the off-balance pose FAST, it hangs there a little longer than any other pose but only a moment (about a fifth of a second, a touch longer for a harder hit — never stuck on tiptoe for half a second), then the LIFTED leg swings back past the standing foot and plants BEHIND it (a longer step for a harder hit), the weight falls back onto it with the knees giving, the arms come down the way they went up, and it settles into the loose stance over its new feet. The standing foot never slides; the stepping foot lifts and plants. Same at any fps and mood (the timing is in seconds).",
  "REACTING ARMS GO STRAIGHT, CLOSE TO THE HEAD: an arm thrown up or brought down by a hit (a block, a flinch, an almost-fall and its recovery) takes the short STRAIGHT way between its poses — the hand passes close by or in front of the face, never swung out on a straight arm round the outside of the head — and its elbow keeps bending the way it bends the whole way (it never flips to the other side mid-move).",
  "GRAB (catch the punch): asked for (getHit result \"grab\"), the fighter sees the fist coming and catches it in BOTH hands — the hands come forward together to where the fist will be, one over and one under it, so they are really on it when it lands; the fist's weight pushes the hands in and the body back a little over planted feet, eyes on the fist; then it lets go back into its stance. Counts as a blocked hit.",
  "PARRY (push the punch aside, then counter fast): asked for (getHit result \"parry\"), the fighter's LEAD forearm meets the punching arm at the wrist from the side just as it arrives (where a block meets it, in front of the face) and sweeps it on up and across in front of the face — never round the outside of the head — while the chest leans back off the line, so the fist goes past the head. No damage, no push back; the guard is back at once and the back hand stays at the chin, so the counter (a kick or a punch) comes fast.",
  "A STOMP IS A STRIKE WITH THE FOOT, straight down on a spot just in front: eyes on the spot; the anticipation goes UP — the knee comes up high while the body rises tall on the standing leg, leaning IN over the spot (leaning back with the arms out reads as a skip or a prance), fists tight at the chest; then the foot slams down fast with the fists driven down; on impact a small jolt and recoil, the knees give only a little and both feet stay down (a deep two-knee landing reads as a hop, a dip onto one leg as a limp). Repeated stomps land on the same spot with the same beat. Mood sets the power and posture: mad = hardest, hunched in; happy = a stamp of joy, chest up, fists pumped; robot = stiff and even, no give.",
  "GETTING HIT: the reaction follows the power and goes the way the hit pushes. Small: a flinch (head snaps back, guard straight back). Medium: a stagger (the back foot steps back to catch the weight, the arms flung forward). Bigger: almost falls and catches itself (THROWN OFF BALANCE, below). Big: knocked down (on the back), stays down, gets up slowly — only with room behind it on the page; with no room it almost falls instead. A block: forearms up in front of the face just before the punch lands, a small push back, no real damage. Planted feet never slide: a stagger steps.",
  "FIGHTING SPOTS AND PERSONAL SPACE: two fighters walk up to each other and meet in the middle, the last step landing straight in the guard (no stop-and-stamp). Each keeps its spot, so the fight stays in the middle of the page: knocked back, it steps back in once its guard is back; after stepping in to attack, it steps back. A strike never brings them so close that their heads or bodies overlap (close is still close enough for an uppercut).",
  "FAST GET-UP IN A FIGHT / FACE YOUR OPPONENT: knocked down in the middle of a fight, a fighter doesn't lie there long — but it never gets up unnaturally fast either (round 12: \"It needs to be two or three times slower\"): about 2 s from lying still to standing when fresh (1.8-2.5 s), slower the more it hurts and in the slow moods, the same at every fps. ONE THING AFTER ANOTHER, never two at once: a short beat lying still; if the attacker stands close, the knees draw up and the legs push it back along the floor to make space (a slow, steady push, never a fast kick); it sits up onto both hands planted behind the hips; loads the arms; then the arms push it up HARD — the \"boom\", the one quick part, you see the push; the legs come under it and extend; and it stands in its loose fighting stand, hands out a little, at fighting distance (no body parts overlap) and facing the other fighter (whoever faces away turns round).",
  "DAMAGE: every hit adds hurt, growing with the fourth power of its power: 25 little hits barely mark a fighter; a few big wound-up hits beat it. The more hurt it is, the more easily it is knocked about, the longer it stays down, the slower it gets its guard back and the more slumped it stands (back bent, head down, hands low); when fully beaten a knock-down is the end.",
  "FAST GET-UP IN A FIGHT — NO SLIDE, BACK HOP: the ground has FRICTION — whatever touches the floor (feet, hands, hips) stays put while it touches it; the body moves only by lifting and placing (never scooting along the floor, except, for now, pushing back when someone stands right over its legs). The rise out of the crouch is a little slower, and the space between the fighters comes from the rise itself: it pushes off and HOPS a little BACK (about 0.1-0.2 body heights), the spine leaning back away from the other, lands on both feet (a small squash held a moment) and settles into the loose stand. THE HOP IS A JUMP (round 15: \"If you hop without anticipation it looks like you're floating, because they can't see your legs push\"): LOAD (knees bent) -> EXTEND (the legs straighten FAST while both feet are still planted where they stand: the take-off you see) -> AIR (the feet leave the floor and come CLOSE together under the body — so the viewer sees the push — legs fairly straight, the body rising quickly) -> LAND (feet apart, coming straight down onto the floor, knees giving) -> settle; the feet only move once they are off the floor.",
  "FIGHTING: a fighter waiting for its moment keeps its hands ready (loose, or its guard if realistic); a strike aims at where the other one IS when it lands; out of reach it first steps in (a fighting step, or a run for a big gap); it never PUNCHES or KICKS someone who is down. PRESS THE ADVANTAGE (by default; hold back only when the user's request says so, e.g. \"blue looks at him and red gets up\"): when the other goes down, the standing one goes over to where it lies and attacks it there (stompDown), and the one down answers — covers up (coverUp), gets hit again, or gets up (fast kipUp, or slowly) and strikes back; when the other is thrown off balance (almost falls, staggers), it closes in at once (a jog for a long gap) straight into a kick, an overhand or an uppercut; a dash punch only with room for a full-speed dash (about 3 body heights apart). A HIT ABOUT EVERY SECOND (round 14): most exchanges are short combos (a lone shot is rare); FLURRIES (round 15): 2-3 quick straight punches, hands mostly alternating, most blocked or parried, ending in a big shot or a kick; NOT ALL PUNCHES (round 15, Arthur: \"70 to 85% of the fight is punches... I like it when they do OTHER stuff — that breaks the pattern\"): the PUNCH BARRAGE (barrage / barraged, the other covering up; its own kind, not a punch) is the most common exchange, plain punch exchanges are under a fifth of the dice, kicks and big shots carry at most one jab, and after two plain punch exchanges running the next is always something else; a kick or big shot not meant to put the other down is thrown a little lighter, so knock-downs stay a highlight; DASH MORE OFTEN: about one fight in three starts far apart (3+ body heights) with the opener dashing in; lift-and-slam only on someone down; the breather between exchanges is a blink (under a tenth of a second), never a pause; and the one who just attacked someone on the floor goes straight back in as it gets up (unless the one getting up strikes first). NEVER A PATTERN, BROKEN AS SOON AS IT SHOWS: the director remembers the kinds of exchanges (barrage, flurry, punch combo, punches into a kick, double kick, kick then punches, big shot, uppercut combo, jabs into a big shot) — never the same kind twice running, never the same two kinds in a row twice in a fight; never the same ground attack twice running; and the answer to a knock-down (hit again, cover up and get up slowly, kip up, kip up and strike straight back) is never the same as the last one.",
  "GUARD STAYS UP IN A FIGHT: between moves a fighter never drops its hands into a relaxed stand — a strike ends at its return to the guard, and stepping back to its spot (after its own attack, or after being knocked back) is done in the guard. The hands only come down for a reason the viewer can see: a big hit (arms flung), being knocked down and getting up, real tiredness at the end. A step back always has a reason (back to its spot after stepping in, keeping its distance) and keeps the guard up. With too little time to settle into the guard, it moves only part of the way there (no snap of the whole body in one picture).",
  "FIGHT LOOK — NO GUARD STANCE BY DEFAULT: a stick-figure fight stands LOOSE between strikes: HANDS LOW — about half as high as in a real guard, around the belly — elbows down by the sides, chin up; not fists up at the face. Hands held higher (at the chest, still no guard) only when the user asks for higher hands (`guard: \"high\"`). Only when the user EXPLICITLY asks for realistic, real-life (MMA/boxing, a fight that could really happen) or educational fighting — never just because it is a fight — does a fighter stand in a real guard (character or move `guard: \"realistic\"`). FEET AND MOVING TOO, not only the hands (round 11): by default a fighter waits with its feet in a NATURAL STAND (about under the hips, a small stagger), not the wide fighting stance, and moves to a spot or closes in with ORDINARY WALKING STEPS (one foot passing the other; a jog or run for a longer gap) with the hands held up a little and NOT swinging — never the boxer's shuffle (front foot, then back foot catching up). A strike steps into the stance it needs and comes back to the natural stand once the combo is over (strike straight after strike keeps its feet). Only `guard: \"realistic\"` keeps the fighting stance and shuffle. Strikes are the same either way (a strike brings the hands up, the free hand comes to the face as the fist lands) and a block still raises the forearms: a block is a reaction, not a stance.",
  "RIGHT GAIT FOR THE DISTANCE (round 14, Arthur: \"walking fast looks weird\"): never a sped-up walk. A figure only walks at a natural walking pace — a natural stride at most, each step about as long as a natural walk's step (about half a second). A way that has to be covered quicker than that is a jog or a run (or, for an attack from far, a dash punch), never a quicker walk; a very short way is one or two calm steps. A lively, fast or angry fighter whose own walk would be brisk jogs into a fight from further than about 0.6 x height and walks a short way in calm steps. Only `guard: \"realistic\"` keeps the quick boxer shuffle.",
  "BOTH HANDS, AND HANDS DOWN WHEN NO ONE IS COMING: a fighter punches with both hands about equally (a run of punches mostly alternates but sometimes doubles up), and big shots (power, overhand, uppercut) come from either hand too. When the other one is down, getting up or staggering for a while (over a second), the standing one lets its hands sink to its belly and breathes, then raises them again just before it goes back in. The hands drop first, as soon as the other goes down: walking back to its spot is done with them down, never seconds of shuffling in the guard.",
  "NO PATTERN IN A FIGHT: every exchange is new — a barrage of punches, punches into a kick, a double kick, a kick then punches, one big shot, a lone jab; the one just hit often counters straight back, or the attacker presses on; some punches are blocked, a big last shot can knock the other down. Never the same rhythm twice: each strike a little harder, softer, quicker or slower than the last, which hand and which strike decided fresh every time. BUSY, NOT STANDING ABOUT: once both are back in their guard, the next exchange starts within a moment (under a second); a fighter already in its guard doesn't settle into it again, and goes back to its spot one way (stepping into its stance on the way, never back and forth). Long pauses only for a reason you can see (down, getting up, out of breath at the end).",
  "ON TIME, EVERY TIME: a strike never lands before the other one can react to it (its stumble done, and a block's forearms already coming up); every moment someone waits for always happens (a walk that ends as a fighting step still arrives; a strike is always done); and a fighter doesn't change its mind about a step for a hair's difference, so every reaction lands exactly on its hit.",
  "A VAGUE FIGHT IS FILLED IN: when the user only asks for \"a fight\" (no detail) and one figure strikes the other, the fight does not just stop there — the attacker presses the advantage (the other is down: walk over and stomp on it, or strike again once it is up; still standing: strike again once its guard is back) and the other answers (blocks and strikes back, gets hit again, or strikes straight back), for a couple more exchanges. A user who described the fight step by step gets exactly what they wrote.",
  "GROUND PUNCH (a ground attack with the fist, groundPunch): from a hop away it crouches (arms back), HOPS up, the punching arm coming forward and up until the fist is cocked high over the head; gravity brings it down and the fist lands ON the body (chest/belly, from how it lies) as it lands on one knee beside it; then it stands back up. Like a stomp, the one lying covers up (coverUp) timed to the landing. RUNNING HAMMER STRIKE: run in on someone down and it does not stop to plant, crouch and hop — the run hands over on a landing with its speed, a quick shallow gather on that foot, a long hop forward and up with the hips still going at about the run's speed, BOTH fists raised high over the head, and both come down hard together ON the body as it lands on one knee beside it (arms up and down the front way, never round the head).",
  "BARRAGE (barrage / barraged): a barrage is punches on ONE STEADY BEAT of 5/12 s (5 pictures at 12 a second: the contact held over 2, then 3 in-betweens) in every mood, energy and speed, the last punch too, ALWAYS LEFT, RIGHT, LEFT, RIGHT: the hands strictly alternate; an uppercut or overhand is thrown by the arm that was cocked, in an arc; no slowing down unless asked for a long all-out barrage. THE SWITCH: one arm straight on target while the other is cocked behind the head; each punch swaps them (both upper arms swing back and forth through down past the ribs, never over the top), with a little lean back between punches and a drive forward into each one — never an elbow-only bend-and-extend. EVERY PUNCH TOUCHES: the engine knows what each fist hits — the other's guard, head or body — on a picture you can see, never thin air; a hard barrage drives the other back step by step. The hit falls on a picture, the fist meets the guard, then fist and guard are driven back together and held there over 2 pictures (the guard, head and chest knocked back ~15-20 degrees), then they recover; the one hit steps back (back foot, then front foot) and the puncher steps in after him so every punch still lands. Mostly straights, with at least one overhand (cocked higher) and one uppercut (cocked low behind the hip), never two of those in a row, and about three strong ones (a bigger lean back), a different mix each time. The one barraged covers up, and the last punch (a body shot from low) gets through to the stomach and folds it over. No limb ever goes through the other's head or body.",
  "LIFT AND SLAM (liftSlam / slammed): grabbing the ankle of the one lying on its back, he hauls the legs up (back still on the floor), swings the body up off the floor and high overhead like a baseball bat, TURNS ROUND under it, and slams it down flat on its back on the other side; THE HELD FOOT IS IN THE HAND every picture from the grab to the slam (the body's place is worked out from the lifter's real hand), the body points out along the swinging arm and never goes into the floor. HEAVY (a body weighs a lot): the haul is a strain at a steady jogging pace (knees bent, leaning back, the back stays flat while the legs rise, then the hips come off), no holding him up (pulled in close past the head, straight overhead only for the turn). FAST AND HARD (Arthur: \"you gotta hit and slam hard, from the weight\" — a slow slam looks like the moon): the lift is a quick heave (a short grip beat, a quick haul, the up-swing — about a second from the grab to the top) and the slam is far faster: EARTH GRAVITY — HEAVY THINGS SPEED UP FAST: over the top it is already speeding up (the up-swing flows straight into the slam, never pausing or slowing at the top); top speed comes quickly (within about 1/12 s) and is held near the ground into the impact — top to impact in a quarter of a second (at 12 fps: one big gap, then two bigger equal ones; a FAST SPAN, so the body may cross big gaps between pictures), with a picture exactly at the top and at the impact; the attacker is YANKED DOWN with it (knees deep, torso pitched forward, the arm straight), so the hand gets low without the arm going round so far — speed comes from the spacing, a short arc and the weight pulling down, never from breaking the windmill or bone rules. THE IMPACT HURTS — a serious crash, never a little tap: a HIT-STOP picture the moment the back hits (flattened hard, head knocked back, arms slapped flat), then the whole body BOUNCES clearly up off the floor and SKIDS on the way it was flying, the arms and legs FLUNG UP hard and the head snapping back; it crashes back down with the limbs still up (they lag the torso), jolts once more as they flop down, and lies hurt only briefly — about 1.1 s from the impact to lying still, in real seconds whatever the mood (something happens every second or two). THE WEIGHT CARRIES THROUGH: after the impact the slammer sways with the weight — forward, then back about 3× less, then still — feet and knees in place; never a squat bounce (unintentional, the weight pulling him; the arms swing along a beat behind), then lets go and stands up ready to fight again. THE IMPACT MOVES BOTH: the one slammed bends (spine whips), bounces a little and skids back the way it was going; the slammer pops up a little with the jolt, then settles — nobody is stiff. But only a little (Arthur: \"if you do it too much ... he's doing the dolphin\"): the slammer's pop about 0.02-0.03 x height for one picture, the bounce about 0.03-0.04 x height, the skid about 0.05 x height, a mild bend that relaxes, no big wave through the body. The turn is a key both figures share, so no picture mixes the two sides. THE ARCH EASES OUT (Arthur, round 16: \"not for one singular frame\"): the slammed body bounces into a gentle arch (the neck dipping a little below the hips — the torso may tip up to 15 degrees past flat — head back on the floor, legs straight and sloping down, both arms straight-ish and relaxed down to the floor, never one sticking up like a pole) and straightens out of it picture by picture, quickly (about 2-3 pictures at 12 a second — longer looks like slow motion), ending in a small curl the other way; never levitating.",
  "FAST THINGS MOVE FAR BETWEEN PICTURES: a slam or throw at full speed may cross a big gap between two pictures — a marked FAST SPAN (the marks fastFrom / fastTo; the slam from the top of the swing to the impact) — up to 4x the usual joint step, but along a smooth path (nothing turns back inside it) and with a picture landing exactly on the impact; everything else keeps the joint-step rule. Speed reads from spacing: a hard hit is a few far-apart pictures, then the impact.",
  "AIR RESISTANCE: a body moving through the air is never rigid — its free arms and legs trail BEHIND the way it moves (lagging a little, whipping through when the direction changes) and it bows against the motion; the shape keeps changing with the speed and direction (liftSlam.ts dragPose).",
  "GRAB, SPIN, THROW (spinThrow / spunThrown; Arthur: \"grab the stick figure and spin, spin, spin, and throw him somewhere\"): on someone standing close, step in, grab the waist with both hands, pull him off his feet and spin on the spot, almost two turns, getting faster; the held one's hips stay in the thrower's real hands every moment. Seen from the side the thrower turns to face wherever the held one is; out at the sides the held body is flung out (head back, legs trailing), passing in front or behind it is small and tucked and the arms hang straight down, so turning round never flips a limb. Let go as the held one swings round to the front (moving forward fast), so he flies off forward in a short arc, lands on his back, slides and jolts, then gets up (kipUp or getUp). A whole body swung round is never so fast that a flung foot jumps too far between pictures.",
  "GROUND FIGHTING (two figures): when a fighter is down, something happens to it — the standing one goes to where it lies (walks round to it, turns to it) and attacks it there (stompDown); the one lying down answers that attack (coverUp, timed to its landing). Ground moves only happen when the scene asks for them or a fight is energetic.",
  "NO PORTAL PUNCHES (round 16, Arthur: \"Red is punching and Blue's far away and he's getting punched — it's like a portal. He needs to actually get close enough to where he can visually hit him\"): a strike only lands where the fist or foot really reaches the other body. Every attack at someone out of reach — a barrage too — first turns to face them (if they are behind) and closes in to its own distance; and the one hit is thrown AWAY from where the hit came from, whichever side that is (it turns to face its attacker first). NO WALKING IN: in a fight, a gap of more than one step is jogged or run (dash for a long one), never walked. HURT FIGHTS HARDER: damage shows in the slumped guard and lower energy, but the slow hurt limp only comes when a fighter is nearly beaten — until then it still gets in there fast. PRESS AFTER A KNOCK-DOWN: whatever put the other down (a planned big shot, an opening dash, the engine itself), the standing one goes straight in on the floor — never seconds of standing about while they lie and get up.",
  "RUN IN ON THE ONE DOWN: in a fight nobody takes a break to stroll over to someone lying on the floor. More than about one step (0.35 body heights) away, the attacker JOGS (a medium way) or RUNS (a long way) there — a walk only for one step, or a slow, sad, tired or badly hurt one — and goes STRAIGHT into the ground attack without stopping to stand: the jog / run ends on a step whose foot comes down right where it needs to stand, and the attack comes out of that stride (a hop-punch hops off that foot, a stomp's knee comes up from the back leg's swing). A lift-and-slam needs both feet down: it runs in and stops leaning in over the body.",
  "LYING IS LYING: a body lying on its back stays ON the floor — hips, back and head down. It may bring its hands up to cover and its knees up with the feet flat on the floor, but a foot or knee never props the body up off the floor (no levitating, no wiggle when it sees something coming: it just gets its hands up and braces). Hit while lying (a stomp), it FOLDS round the hit (shoulders and legs curl up, the belly dented), the legs jolt up and SLAM back down on the floor, then it lies there or gets up.",
  "GRABS AND STRIKES TOUCH: a hand that grabs and a foot that stomps really touch the other body (within a line's width), worked out from where that body really lies at that moment — never a guessed spot in the air. The one on the floor reacts on the very frame it is touched.",
  "KIP-UP: a fighter who isn't beaten gets up from its back FAST, the way FAST GET-UP IN A FIGHT says (push away with the legs if someone is close, sit up onto the hands, a hard visible arm push, land crouched, stand loose with the hands out a little), a fighting distance from the one in front (never inside them). The slow hand-on-the-knee get-up is for the hurt.",
  "STOMP DOWN: a stomp on someone on the floor winds up the opposite way — the knee comes up HIGH over the body, the chest rising and leaning back a little, the arms rising — hangs a moment, then the foot drives straight down onto the belly, fast, the hips dropping into it; the eyes stay on the spot all the way. Walking up to it, the last step lands straight into the knee lift (no slowing down and standing first). The one below sees it coming (head up), covers (knees and fists up) and is driven flat when it lands, then curls up hurt.",
  "EVERY WALK LIFTS ITS FEET: whatever the mood (sad, tired, hurt, robot, low energy), a walk is a real walk — each foot leaves the floor going up first, then swings forward clearly off the floor (never under about 4-5% of the body's height, even on the first and last steps) and plants; a mood shows in the lean, the head, the pace and the step length, never by sliding the feet along the floor. A short walk before a kick or punch with nobody to fight (kicking the floor alone) is a real walk too, not a fighting shuffle.",
  "STAND UP STRAIGHT: a figure standing still stands upright — hips over the middle of its feet, knees nearly straight (a slight give, not a bend), back nearly upright, feet about hip width (a fighting stance at most). Waiting in a fight, resting after one, or waiting for a ball, the knees stay nearly straight; tired or hurt shows in the back, the head and the hands (only a little in the knees), and a really tired fighter may bend over with its hands on its knees. A crouch, lunge or half-fall is never a resting pose unless the user asks for it (a squat, a sit, a sneaky crouch, a real boxing guard).",
  "STEP OFF, FIGHT FROM WHERE YOU ARE: after a stomp, hop-punch or slam the attacker gets its guard up and steps back a short fighting distance from the one on the floor (never standing on or over the body), so they get up right where they lie — the floor has friction, nobody slides out from under anyone. After a hit or a get-up a fighter fights on from where it is; it only walks back to its spot when the fight has drifted far off it (over about 1.6 heights).",
];

export type MoveLesson = {
  id: string;
  title: string;
  about: string;
  // The library's own key poses for this move at natural / normal / energy 0.5, facing right, starting at
  // x = 0, t = 0: time (s), forward travel (px), height of the lowest foot (px), planted feet, pose angles.
  keyPoses: { t: number; dx: number; lift: number; feet: string; pose: PoseAngles }[];
  marks: Record<string, number>;
  seconds: number;
};

const round = (v: number, d = 2) => Math.round(v * 10 ** d) / 10 ** d;

export function moveLesson(id: string, entry: MoveEntry, params: Record<string, unknown> = {}, height = 300): MoveLesson {
  const settings: MoveSettings = { height, style: "natural", speed: "normal", energy: 0.5 };
  const start: Stance = { t: 0, x: 0, facing: "right", pose: STAND };
  const out = entry.run(start, params, settings);
  return {
    id, title: entry.title, about: entry.about,
    keyPoses: out.keys.map((k) => ({
      t: round(k.t), dx: round(k.x), lift: round(k.lift ?? 0, 1), feet: (k.contacts ?? []).map((c) => c[0]).join("") || "none",
      pose: Object.fromEntries(Object.entries(k.pose).map(([name, value]) => [name, round(value, 0)])) as PoseAngles,
    })),
    marks: Object.fromEntries(Object.entries(out.marks).map(([name, t]) => [name, round(t)])),
    seconds: round(out.end.t),
  };
}

// What each style changes, in numbers the AI can reason about.
export const styleLesson = () => MOVE_STYLES.map((style) => ({
  style,
  changes: STYLE_CHANGES[style],
  speedUpAndSlowDown: RAMP_SCALE[style] === 0 ? "none (instant)" : `${RAMP_SCALE[style]} x natural`,
}));

// The full lesson pack for the AI (Phase 3 sends this before the user's request).
export function lessonPack(moves: Record<string, MoveEntry>, exampleParams: Record<string, Record<string, unknown>> = {}) {
  return {
    principles: PRINCIPLES,
    styles: styleLesson(),
    speeds: MOVE_SPEEDS,
    moves: Object.entries(moves).map(([id, entry]) => moveLesson(id, entry, exampleParams[id] ?? {})),
  };
}
